GN['de.es'] = {
A1: [
 {t:'Pronombres y los verbos sein y haben',
  b:`<p>Los pronombres personales son [[ich]] (yo), [[du]] (tú), [[er]] / [[sie]] / [[es]] (él / ella / ello), [[wir]] (nosotros), [[ihr]] (vosotros), [[sie]] (ellos) y el formal [[Sie]] (usted, ustedes).</p><div class="tblwrap"><table><tr><th></th><th>sein (ser / estar)</th><th>haben (tener)</th></tr><tr><td>ich</td><td>[[bin]]</td><td>[[habe]]</td></tr><tr><td>du</td><td>[[bist]]</td><td>[[hast]]</td></tr><tr><td>er / sie / es</td><td>[[ist]]</td><td>[[hat]]</td></tr><tr><td>wir / sie / Sie</td><td>[[sind]]</td><td>[[haben]]</td></tr><tr><td>ihr</td><td>[[seid]]</td><td>[[habt]]</td></tr></table></div><p class="tip">Un solo verbo, [[sein]], sirve para «ser» y «estar»: [[Ich bin müde.]] = Estoy cansado.</p>`,
  ex:['Soy estudiante.','Eres muy amable.','Tenemos un coche.','Ella tiene dos hijos.'],
  q:['«Estoy cansado»:','«Tenemos un gato»:']},
 {t:'Género y artículos',
  b:`<p>En alemán hay tres géneros: masculino, femenino y neutro, y muchas veces no coinciden con el español. Los sustantivos se escriben siempre con mayúscula. Aprende cada palabra con su artículo: [[der Tisch]] (masc.), [[die Lampe]] (fem.), [[das Buch]] (neutro). En plural los tres son [[die]].</p><p>El artículo indefinido es [[ein]] para masculino y neutro y [[eine]] para femenino: [[ein Tisch]], [[eine Lampe]], [[ein Buch]].</p><p class="tip">Después de «tengo» el artículo masculino cambia: [[Ich habe einen Bruder.]] Verás por qué en la lección del acusativo.</p>`,
  ex:['La mesa es grande.','La lámpara es nueva.','El libro es interesante.','Tengo un hermano y una hermana.'],
  q:['«El libro»: ___ Buch','«Un gato» (die Katze):']},
 {t:'El presente y el orden de las palabras',
  b:`<p>Toma la raíz del infinitivo ([[wohn]]-en) y añade las terminaciones: [[ich wohne]], [[du wohnst]], [[er wohnt]], [[wir wohnen]], [[ihr wohnt]], [[sie wohnen]].</p><p>La regla más importante: en una oración afirmativa el verbo va siempre en <b>segunda posición</b>. Si la oración empieza con otra cosa, el sujeto pasa detrás del verbo: [[Ich spiele morgen.]] → [[Morgen spiele ich.]]</p><p>Las preguntas empiezan con la palabra interrogativa ([[Wo wohnst du?]]) o, si se responden con sí/no, con el verbo ([[Wohnst du hier?]]).</p>`,
  ex:['Vivo en Berlín.','Él trabaja hoy.','Mañana jugamos al fútbol.','¿Dónde vives?'],
  q:['«tú vives» (wohnen): du ___','«Mañana juego al tenis»:']},
 {t:'La negación: nicht y kein',
  b:`<p>[[kein]] niega un sustantivo que llevaría [[ein]] o ningún artículo: [[Ich habe ein Auto.]] → [[Ich habe kein Auto.]] Toma las mismas terminaciones que ein: [[keine Zeit]], [[keinen Bruder]].</p><p>[[nicht]] niega todo lo demás: verbos, adjetivos, nombres, sustantivos con der/die/das. Suele ir al final o delante de la palabra que niega: [[Er kommt nicht.]] [[Das ist nicht teuer.]]</p>`,
  ex:['No tengo coche.','Eso no es caro.','Él no viene hoy.','No tenemos tiempo.'],
  q:['«No tengo tiempo»:','«El té no está caliente»:']}
],
A2: [
 {t:'El acusativo',
  b:`<p>El complemento directo (¿a quién?, ¿qué?) va en acusativo. Solo cambia el masculino: [[der]] → [[den]], [[ein]] → [[einen]], [[kein]] → [[keinen]]. El femenino, el neutro y el plural no cambian.</p><p>[[Ich sehe den Mann.]] [[Sie kauft einen Mantel.]] [[Ich sehe die Frau.]]</p><p>Pronombres: [[mich]] (me), [[dich]] (te), [[ihn]] (lo), [[sie]] (la), [[es]], [[uns]] (nos), [[euch]] (os), [[sie]] (los), [[Sie]] (lo/la, usted).</p>`,
  ex:['Veo al hombre.','Ella compra un abrigo.','Te quiero.','¿Lo conoces?'],
  q:['«Veo al perro» (der Hund):','«Necesito un bolígrafo» (der Kugelschreiber):']},
 {t:'El dativo y las preposiciones',
  b:`<p>El dativo responde a «¿a quién?» y va después de las preposiciones [[mit]] (con), [[bei]] (en casa de), [[nach]] (a, después de), [[von]] (de), [[zu]] (a), [[aus]] (de), [[seit]] (desde).</p><div class="tblwrap"><table><tr><th>masc.</th><th>fem.</th><th>neutro</th><th>plural</th></tr><tr><td>[[dem]] / [[einem]]</td><td>[[der]] / [[einer]]</td><td>[[dem]] / [[einem]]</td><td>[[den]] (+n)</td></tr></table></div><p>Pronombres: [[mir]], [[dir]], [[ihm]], [[ihr]], [[uns]], [[euch]], [[ihnen]]. Algunos verbos llevan siempre dativo: [[helfen]], [[danken]], [[gefallen]]: [[Ich helfe dir.]] = Te ayudo.</p>`,
  ex:['Voy en autobús.','Él vive con su madre.','Le doy un libro al niño.','Después de comer tomamos té.'],
  q:['«en coche» (das Auto):','«Te ayudo»:']},
 {t:'El pretérito perfecto: haben / sein + participio',
  b:`<p>Al hablar del pasado se usa sobre todo el Perfekt: una forma de [[haben]] en segunda posición y el participio al final: [[Ich habe Kaffee getrunken.]]</p><p>Participios regulares: ge- + raíz + -t: [[kaufen]] → [[gekauft]]. Los irregulares terminan en -en: [[trinken]] → [[getrunken]], [[schlafen]] → [[geschlafen]].</p><p class="tip">Los verbos de movimiento o cambio de estado van con [[sein]]: [[Wir sind nach Hamburg gefahren.]] [[Er ist gekommen.]]</p>`,
  ex:['Tomé café.','Fuimos a Hamburgo.','¿Dormiste bien?','Ella compró un vestido.'],
  q:['«Compré un libro»:','«Él se fue a casa (en coche)»:']},
 {t:'Los verbos modales',
  b:`<p>[[können]] (poder, saber), [[müssen]] (tener que), [[wollen]] (querer), [[dürfen]] (tener permiso), [[sollen]] (deber) y [[möchten]] (querría). El modal va en segunda posición y el verbo principal, en infinitivo, al final: [[Ich kann schwimmen.]]</p><p>En singular cambia la vocal: [[ich kann]], [[du kannst]], [[er kann]]; [[ich muss]], [[er muss]]; [[ich will]], [[er will]]. Con ich y er no hay terminación.</p>`,
  ex:['Sé nadar.','Tienes que trabajar hoy.','Queremos ir a Italia.','Quisiera un café.'],
  q:['«No puedo venir»:','«Ella tiene que estudiar»:']}
],
B1: [
 {t:'Oraciones subordinadas: weil, dass, wenn, ob',
  b:`<p>En una subordinada con [[weil]] (porque), [[dass]] (que), [[wenn]] (si, cuando) u [[ob]] (si, en preguntas indirectas), el verbo conjugado va al <b>final</b>: [[Ich bleibe zu Hause, weil ich krank bin.]]</p><p>Si la subordinada va primero, la principal empieza por el verbo: [[Wenn es regnet, nehme ich einen Schirm.]]</p><p class="tip">Las dos oraciones siempre se separan con coma.</p>`,
  ex:['Me quedo en casa porque estoy enfermo.','Creo que tiene razón.','Si llueve, cojo un paraguas.','¿Sabes si viene ella?'],
  q:['«porque estoy cansado»:','«Sé que él trabaja»:']},
 {t:'El Präteritum y los verbos separables',
  b:`<p>Con [[sein]], [[haben]] y los modales se usa el pasado simple incluso al hablar: [[ich war]], [[ich hatte]], [[ich konnte]], [[ich musste]]. En los relatos escritos lo usan todos los verbos: [[er ging]], [[sie kaufte]].</p><p>Muchos verbos tienen un prefijo separable: [[aufstehen]] (levantarse), [[anrufen]] (llamar), [[einkaufen]] (hacer la compra). En presente y en pasado simple el prefijo va al final: [[Ich stehe um sieben Uhr auf.]] [[Er rief mich an.]]</p>`,
  ex:['Ayer estaba cansado.','No teníamos tiempo.','Me levanto a las siete.','Me llamó ayer.'],
  q:['«Ayer estuve en casa»:','«Me levanto a las seis»:']},
 {t:'Terminaciones del adjetivo y comparación',
  b:`<p>Delante de un sustantivo el adjetivo lleva terminación. Después de [[der]]/[[die]]/[[das]] suele ser -e: [[der gute Film]]. Después de [[ein]] el adjetivo muestra el género: [[ein guter Film]], [[eine gute Idee]], [[ein gutes Buch]]. Sin artículo toma la terminación del artículo: [[heißer Tee]] (acusativo [[heißen Tee]]).</p><p>Comparación: -er + [[als]] y am -sten: [[groß]] → [[größer als]] → [[am größten]]. Las palabras cortas suelen añadir diéresis: [[alt]] → [[älter]].</p>`,
  ex:['Es una buena película.','Tomo té caliente.','El piso nuevo es más grande que el viejo.','Él es el corredor más rápido.'],
  q:['«una casa grande» (das Haus):','«mayor que yo»:']}
],
B2: [
 {t:'La voz pasiva',
  b:`<p>La pasiva pone la acción en primer plano: [[werden]] + participio. Presente: [[Das Haus wird renoviert.]] Pasado: [[Der Brief wurde geschickt.]]</p><p>Quien realiza la acción se introduce con [[von]]: [[Das Buch wurde von Goethe geschrieben.]]</p><p class="tip">Sin sujeto, la pasiva describe una actividad general: [[Hier wird Deutsch gesprochen.]] = Aquí se habla alemán.</p>`,
  ex:['Están reformando la casa.','La carta se envió ayer.','Aquí se habla alemán.','El puente se construyó en 1900.'],
  q:['«Están reparando el coche»:','«El libro se escribió en 1990»:']},
 {t:'El Konjunktiv II: deseos y condiciones irreales',
  b:`<p>Para situaciones irreales se usa el Konjunktiv II. Con la mayoría de los verbos es [[würde]] + infinitivo: [[Ich würde reisen.]] = Viajaría. Sein, haben y los modales tienen formas propias: [[wäre]], [[hätte]], [[könnte]], [[müsste]].</p><p>[[Wenn ich Zeit hätte, würde ich reisen.]] = Si tuviera tiempo, viajaría.</p><p class="tip">También hace corteses las peticiones: [[Könnten Sie mir helfen?]]</p>`,
  ex:['Si tuviera tiempo, viajaría.','Me gustaría ser médico.','¿Podría ayudarme?','Yo que tú, no lo haría.'],
  q:['«Si yo fuera rico»:','«Compraría una casa»:']},
 {t:'Oraciones de relativo',
  b:`<p>Los pronombres relativos se parecen al artículo determinado: [[der]], [[die]], [[das]]; en plural [[die]]. El género lo da el sustantivo; el caso, su función en la oración de relativo: [[der Mann, der dort steht]] (que está allí) / [[die Frau, die ich kenne]] (a la que conozco).</p><p>El verbo va al final. Con preposición, la preposición va primero: [[die Stadt, in der ich wohne]] (en la que vivo).</p>`,
  ex:['El hombre que está allí es mi profesor.','Es la mujer a la que conozco.','El libro que lees es bueno.','La ciudad en la que vivo es pequeña.'],
  q:['«el hombre que trabaja aquí»:','«la ciudad en la que vivo»:']}
],
C1: [
 {t:'El genitivo y sus preposiciones',
  b:`<p>El genitivo expresa posesión: [[des]] / [[eines]] (masc. y neutro, el sustantivo añade -s o -es), [[der]] / [[einer]] (fem. y plural): [[das Auto meines Vaters]] = el coche de mi padre.</p><p>En lenguaje formal varias preposiciones rigen genitivo: [[trotz]] (a pesar de), [[wegen]] (a causa de), [[während]] (durante), [[infolge]] (como consecuencia de), [[aufgrund]] (debido a).</p><p class="tip">En la lengua hablada oirás [[wegen dem Regen]], pero por escrito usa el genitivo: [[wegen des Regens]].</p>`,
  ex:['El coche de mi padre es viejo.','A pesar de la lluvia, salimos a pasear.','A causa de la crisis, muchos perdieron su trabajo.','Durante sus estudios trabajaba.'],
  q:['«a pesar de la lluvia»:','«el coche de mi padre»:']},
 {t:'El Konjunktiv I: el estilo indirecto',
  b:`<p>Las noticias y los textos formales transmiten lo que dijo otra persona con el Konjunktiv I: raíz + -e. Las formas más frecuentes son las de 3.ª persona: [[er sei]], [[er habe]], [[er komme]], [[er wohne]].</p><p>[[Er sagt, er sei krank.]] = Dice que está enfermo (quien habla no lo garantiza).</p><p class="tip">Si la forma coincide con el indicativo, se usa el Konjunktiv II: [[sie hätten]] en lugar de sie haben.</p>`,
  ex:['Dice que está enfermo.','Afirma que no tiene tiempo.','El ministro declaró que la situación era estable.','Dicen que ahora vive en Viena.'],
  q:['«Dice que está cansado» (estilo indirecto):','«Dice que no tiene dinero» (estilo indirecto):']}
],
C2: [
 {t:'Las partículas modales',
  b:`<p>Palabritas como [[doch]], [[ja]], [[mal]], [[halt]] y [[eben]] no cambian los hechos, pero dan color al tono, y los nativos las usan constantemente.</p><p>[[doch]] en peticiones, insistencia amable: [[Komm doch vorbei!]] = ¡Pásate! [[ja]], algo sabido o sorprendente: [[Das ist ja interessant!]] [[mal]] suaviza una petición: [[Mach mal eine Pause.]] [[halt]] / [[eben]], «es lo que hay»: [[Das ist halt so.]]</p>`,
  ex:['¡Pásate por aquí!','¡Pues qué interesante!','Es lo que hay.','Tómate un descanso.'],
  q:['Un amable «¡Pásate!»:','«¡Anda, qué interesante!» (sorpresa):']},
 {t:'Atributos extendidos y estilo nominal',
  b:`<p>El alemán formal mete una oración entera delante del sustantivo: [[die von ihm geschriebene Arbeit]] = el trabajo escrito por él. El participio lleva la terminación normal del adjetivo.</p><p>Los textos escritos prefieren sustantivos a verbos: [[nachdem sie das Studium abgeschlossen hatte]] → [[nach Abschluss des Studiums]] (tras terminar los estudios). Son típicas las expresiones fijas: [[zur Diskussion stellen]], [[in Frage kommen]].</p>`,
  ex:['El trabajo escrito por él recibió elogios.','La casa construida en 1900 sigue en pie.','Tras terminar los estudios encontró trabajo.','La propuesta se sometió a debate.'],
  q:['«el libro escrito por ella»:','Estilo nominal de «después de que terminó sus estudios»:']}
]};
